<?php if($purpose==='password_change'):?><label>New password<input type="password" name="new_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><?php endif;?><button class="ac-primary" type="submit"><?=$purpose==='email_change'?'Verify and change email':'Verify and change password'?></button></form>
