<?php else:?><form method="post" action="layout.php?page=profile" data-portal-save class="ac-form"><input type="hidden" name="csrf" value="<?=$se($_SESSION['profile_csrf'])?>"><input type="hidden" name="profile_action" value="security_start"><input type="hidden" name="purpose" value="<?=$purpose?>">
<?php if($purpose==='email_change'):?><label>New email address<input type="email" name="new_email" maxlength="100" autocomplete="email" required><small>We’ll send the code to this new address. It must not belong to another account.</small></label><?php else:?><p>The code will be sent to your current registered email address.</p><?php endif;?>
